import numpy as np
from scipy import stats
from sklearn.linear_model import LogisticRegression
from sklearn.feature_selection import mutual_info_classif
from collections import defaultdict

MAX_DRIVERS = 5

def design(feats):
    # Check if we have any significant associations
    if len(feats.ids) == 0:
        return Design(drivers=(), columns=(), products=(), loadings={})

    # Calculate effect sizes and p-values for all features
    effects = []
    for i, fid in enumerate(feats.ids):
        col = feats.column(fid)
        x = feats.x[:, col]
        y = feats.y

        # Calculate mean difference
        mean_y1 = np.mean(x[y == 1])
        mean_y0 = np.mean(x[y == 0])
        effect_size = mean_y1 - mean_y0

        # Welch's t-test
        group1 = x[y == 1]
        group0 = x[y == 0]
        if len(group1) > 1 and len(group0) > 1:
            t_stat, p_val = stats.ttest_ind(group1, group0, equal_var=False)
        else:
            p_val = 1.0

        effects.append((fid, effect_size, p_val))

    # Sort by effect size (absolute value)
    effects.sort(key=lambda x: abs(x[1]), reverse=True)

    # Remove near-duplicates based on correlation
    keep_features = set()
    correlations = {}

    # Build correlation matrix
    for i, fid1 in enumerate(feats.ids):
        for j, fid2 in enumerate(feats.ids):
            if i < j:
                col1 = feats.column(fid1)
                col2 = feats.column(fid2)
                corr = np.corrcoef(feats.x[:, col1], feats.x[:, col2])[0, 1]
                correlations[(fid1, fid2)] = abs(corr)

    # Filter out highly correlated features
    for fid, _, _ in effects:
        if fid in keep_features:
            continue
        keep_features.add(fid)
        # Remove correlated features
        to_remove = set()
        for other_fid in keep_features:
            if other_fid != fid and (other_fid, fid) in correlations:
                if correlations[(other_fid, fid)] >= 0.6:
                    to_remove.add(other_fid)
        keep_features -= to_remove

    # Select top features by effect size
    selected_features = [fid for fid, _, _ in effects[:10] if fid in keep_features]

    # Check for strong associations
    if len(selected_features) == 0:
        return Design(drivers=(), columns=(), products=(), loadings={})

    # Try to find a mechanism - look for strong effect sizes
    strong_effects = [(fid, effect) for fid, effect, p in effects if abs(effect) > 0.15 and p < 0.1]

    # If we have strong effects, check if they're consistent
    if len(strong_effects) >= 2:
        # Look for products between top features
        top_features = [fid for fid, _ in strong_effects[:3]]
        products = []

        # Create pairwise products
        for i, f1 in enumerate(top_features):
            for j, f2 in enumerate(top_features[i+1:], i+1):
                products.append((f1, f2))

        # Return best drivers
        drivers = tuple([fid for fid, _ in strong_effects[:MAX_DRIVERS]])
        columns = tuple(selected_features)
        return Design(
            drivers=drivers,
            columns=columns,
            products=tuple(products),
            loadings={fid: 1.0 for fid in selected_features}
        )

    # Default case - return empty design if no clear mechanism
    return Design(drivers=(), columns=(), products=(), loadings={})

